const avatarUrl = (svg) => `data:image/svg+xml,${encodeURIComponent(svg)}`;

const FEMALE_AVATARS = [
  {
    id: "adventurer-female-1",
    gender: "female",
    tags: ["custom", "adventurer", "long hair", "brown hair", "earrings"],
    url: avatarUrl(ADVENTURER_FEMALE_1),
  },
  {
    id: "adventurer-female-2",
    gender: "female",
    tags: ["custom", "adventurer", "long hair", "blonde hair", "earrings"],
    url: avatarUrl(ADVENTURER_FEMALE_2),
  },
  {
    id: "adventurer-female-3",
    gender: "female",
    tags: ["custom", "adventurer", "long hair", "auburn hair", "glasses", "earrings"],
    url: avatarUrl(ADVENTURER_FEMALE_3),
  },
  {
    id: "adventurer-female-4",
    gender: "female",
    tags: ["custom", "adventurer", "long hair", "black hair", "earrings"],
    url: avatarUrl(ADVENTURER_FEMALE_4),
  },
];

const MALE_AVATARS = [
  {
    id: "adventurer-male-1",
    gender: "male",
    tags: ["custom", "adventurer", "short hair", "purple hair"],
    url: avatarUrl(ADVENTURER_MALE_1),
  },
  {
    id: "adventurer-male-2",
    gender: "male",
    tags: ["custom", "adventurer", "short hair", "black hair", "mustache"],
    url: avatarUrl(ADVENTURER_MALE_2),
  },
  {
    id: "adventurer-male-3",
    gender: "male",
    tags: ["custom", "adventurer", "short hair", "black hair", "glasses"],
    url: avatarUrl(ADVENTURER_MALE_3),
  },
  {
    id: "adventurer-male-4",
    gender: "male",
    tags: ["custom", "adventurer", "short hair", "red hair", "mustache"],
    url: avatarUrl(ADVENTURER_MALE_4),
  },
];

// Interleave the pools so the unfiltered grid reads as a mixed crowd.
const interleaved = [];
const maxLen = Math.max(FEMALE_AVATARS.length, MALE_AVATARS.length);
for (let i = 0; i < maxLen; i++) {
  if (FEMALE_AVATARS[i]) interleaved.push(FEMALE_AVATARS[i]);
  if (MALE_AVATARS[i]) interleaved.push(MALE_AVATARS[i]);
}
export const DOODLE_AVATARS = interleaved;

/**
 * Subset of the avatar set for a gender label ("Male"/"Female", any casing).
 * Unknown/empty labels return everything.
 */
export const avatarsForGender = (genderLabel = "") => {
  const key = String(genderLabel).trim().toLowerCase();
  if (key === "male") return DOODLE_AVATARS.filter((a) => a.gender === "male");
  if (key === "female") return DOODLE_AVATARS.filter((a) => a.gender === "female");
  return DOODLE_AVATARS;
};

/** Stable avatar URL from a specific presentation pool — used for seed data.
 *  Anything other than "female"/"male" (e.g. an unknown gender) draws from the
 *  full mixed set. */
export const getGenderAvatar = (presentation, index = 0) => {
  const list =
    presentation === "female" ? FEMALE_AVATARS
    : presentation === "male" ? MALE_AVATARS
    : DOODLE_AVATARS;
  return list[index % list.length].url;
};

export const getDoodleAvatarById = (id) =>
  DOODLE_AVATARS.find((a) => a.id === id) || null;

/** No-op passthrough kept for callers that upgrade previously-stored avatar
 *  URLs — this avatar set has no legacy format to migrate. */
export const upgradeDoodleAvatarUrl = (url) => url;
